import{c as t,Q as s,j as i,m as a}from"./chunks/framework.DM-btvs7.js";const u=JSON.parse('{"title":"What is SafeTS?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-safets.md","filePath":"guide/what-is-safets.md"}'),o={name:"guide/what-is-safets.md"};function r(n,e,l,p,h,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="what-is-safets" tabindex="-1">What is SafeTS? <a class="header-anchor" href="#what-is-safets" aria-label="Permalink to &quot;What is SafeTS?&quot;">​</a></h1><p>SafeTS is a static analysis CLI for TypeScript that detects runtime crash patterns the TypeScript compiler deliberately allows — even with <code>strict: true</code>.</p><h2 id="the-gap-safets-fills" tabindex="-1">The gap SafeTS fills <a class="header-anchor" href="#the-gap-safets-fills" aria-label="Permalink to &quot;The gap SafeTS fills&quot;">​</a></h2><p>TypeScript is excellent at catching type errors. But some patterns are structurally valid TypeScript that crash at runtime:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// TypeScript compiles this without errors</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//                           ^^^^^^^^^^</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//                           crashes if PORT is not set</span></span></code></pre></div><p>TypeScript knows <code>process.env.PORT</code> is <code>string | undefined</code>. It even knows <code>.toString()</code> doesn&#39;t exist on <code>undefined</code>. But it still compiles — because TypeScript&#39;s philosophy is to trust the developer&#39;s intent.</p><p>SafeTS is the second layer. It uses the TypeScript Compiler API to walk your AST with full type information and flag these patterns explicitly.</p><h2 id="what-safets-is-not" tabindex="-1">What SafeTS is not <a class="header-anchor" href="#what-safets-is-not" aria-label="Permalink to &quot;What SafeTS is not&quot;">​</a></h2><ul><li><strong>Not a TypeScript fork</strong> — it uses your existing compiler</li><li><strong>Not a runtime tool</strong> — it runs before execution, at analysis time</li><li><strong>Not a code modifier</strong> — it never touches your source files</li><li><strong>Not a replacement for TypeScript</strong> — it&#39;s a complement</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Loads your <code>tsconfig.json</code> and builds a typed program</li><li>Walks the AST of every source file</li><li>For each node, checks the TypeScript type at that location</li><li>Reports nodes where the type is nullable but the access is unguarded</li><li>Simulates the crash path so you understand exactly what would happen at runtime</li></ol><h2 id="tested-on-real-projects" tabindex="-1">Tested on real projects <a class="header-anchor" href="#tested-on-real-projects" aria-label="Permalink to &quot;Tested on real projects&quot;">​</a></h2><p>SafeTS was validated against <a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noreferrer"><code>google-gemini/gemini-cli</code></a>, a production TypeScript monorepo with 300+ source files.</p><p><strong>Results:</strong> 297 findings including 10 confirmed production bugs in <code>clearcut-logger.ts</code>, <code>sessionSummaryUtils.ts</code>, <code>baseLlmClient.ts</code>, and others — patterns TypeScript 5.x with strict mode missed entirely.</p>`,14)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
